package mux

import (
	"net/http"
	"testing"
)

// Hidden F2P conformance test (ADR-0032.1 S4). A GET whose only GET route has an
// unsatisfied query constraint, sharing its path with a POST route, must yield
// ErrNotFound (404), not ErrMethodMismatch (405).
func TestGHXConformanceInvalidQueryIsNotFound(t *testing.T) {
	emptyHandler := func(w http.ResponseWriter, r *http.Request) {}
	r := NewRouter()
	r.HandleFunc("/api", emptyHandler).Methods("POST")
	r.HandleFunc("/api", emptyHandler).Queries("time", "{time:[0-9]+}").Methods("GET")
	req, _ := http.NewRequest("GET", "http://localhost/api?time=-4", nil)
	match := new(RouteMatch)
	if r.Match(req, match) {
		t.Fatal("should not match: query constraint unsatisfied")
	}
	if match.MatchErr != ErrNotFound {
		t.Fatalf("MatchErr = %v, want ErrNotFound (404 conformance)", match.MatchErr)
	}
}
GHXEOF
